public boolean searchMatrix(int[][] matrix, int target) {
    int n = matrix[0].length;
    for (int[] row : matrix) {
        if (target >= row[0] && target <= row[n - 1]) {
            int lo = 0, hi = n - 1;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (row[mid] == target) return true;
                else if (row[mid] < target) lo = mid + 1;
                else hi = mid - 1;
            }
            return false;
        }
    }
    return false;
}

