    n = len(matrix[0])
    for row in matrix:
        if row[0] <= target <= row[-1]:
            lo, hi = 0, n - 1
            while lo <= hi:
                mid = lo + (hi - lo) // 2
                if row[mid] == target:
                    return True
                elif row[mid] < target:
                    lo = mid + 1
                else:
                    hi = mid - 1
            return False
    return False

